import{_ as t,c as a,o as s,ag as i}from"./chunks/framework.Ce1dNOE6.js";const c=JSON.parse('{"title":"theme","description":"","frontmatter":{},"headers":[],"relativePath":"api/modules/theme.md","filePath":"api/modules/theme.md","lastUpdated":1785055892000}'),l={name:"api/modules/theme.md"};function o(r,e,n,h,p,d){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="theme" tabindex="-1">theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;theme&quot;">​</a></h1><p>Theme module: restyle elements without touching them individually.</p><p>local theme = basalt.use(&quot;theme&quot;) theme.set({ Button = { background = basalt.rgb(&quot;#89b4fa&quot;) } }) theme.apply(frame, { Label = { foreground = colors.yellow } })</p><p>theme.set() changes CLASS defaults: every element that never set the property explicitly follows immediately (including existing ones). theme.apply() assigns per element (explicit override) on a subtree. A <code>states</code> table defines property overrides while named states are active.</p><p>Values may be plain values or functions (dynamic values). Reactive &quot;{...}&quot; strings only work in apply(), not in set() — defaults are shared between elements, use a function instead.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="theme-set-themetable" tabindex="-1">theme.set(themeTable) <a class="header-anchor" href="#theme-set-themetable" aria-label="Permalink to &quot;theme.set(themeTable)&quot;">​</a></h3><p>Changes class-level defaults for the given element types.</p><ul><li><strong>themeTable</strong> (<code>table</code>) Map of type name -&gt; { property = value, states = {...} }</li></ul><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">theme.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ Button </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { background </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> colors.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } })</span></span></code></pre></div><h3 id="theme-applypreset-presetorname" tabindex="-1">theme.applyPreset(presetOrName) <a class="header-anchor" href="#theme-applypreset-presetorname" aria-label="Permalink to &quot;theme.applyPreset(presetOrName)&quot;">​</a></h3><p>Applies a preset (by name or as a table from theme.load) via theme.set.</p><ul><li><p><strong>presetOrName</strong> (<code>string|table</code>) Preset name or loaded preset table</p></li><li><p><strong>returns</strong> <strong>colors</strong> (<code>table</code>) The preset&#39;s color tokens</p></li></ul><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> theme.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">applyPreset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;basalt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="theme-load-path" tabindex="-1">theme.load(path) <a class="header-anchor" href="#theme-load-path" aria-label="Permalink to &quot;theme.load(path)&quot;">​</a></h3><p>Loads a theme file and registers it as a preset. Returns (name, preset); pass the name straight into applyPreset: theme.applyPreset(theme.load(&quot;themes/obsidian.json&quot;)) .json files are parsed as JSON, everything else with textutils.unserialize.</p><ul><li><p><strong>path</strong> (<code>string</code>) Path to the theme file</p></li><li><p><strong>returns</strong> <strong>name</strong> (<code>string</code>) The registered preset name</p></li><li><p><strong>returns</strong> <strong>preset</strong> (<code>table</code>) The resolved preset ({ colors, styles })</p></li></ul><h3 id="theme-apply-root-themetable" tabindex="-1">theme.apply(root, themeTable) <a class="header-anchor" href="#theme-apply-root-themetable" aria-label="Permalink to &quot;theme.apply(root, themeTable)&quot;">​</a></h3><p>Applies properties to every matching element in a subtree (by type name).</p><ul><li><strong>root</strong> (<code>Element</code>) Root element</li><li><strong>themeTable</strong> (<code>table</code>) Map of class names to properties/state styles</li></ul>',20)])])}const u=t(l,[["render",o]]);export{c as __pageData,u as default};
